// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, uint v) public {
        address[] memory emptyTos = new address[](0);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, emptyTos, v));
        assertTrue(!success, "transfer with empty array should revert");
    }
}

